def extract_pdf(pdf_path: Path, workspace_root: Path, *, title: str | None = None) -> dict[str, Any]:
    """Extract native PDF text into workspace/papers/<sha256>/{source.md,source.json}."""

    source, data, digest = _read_pdf(Path(pdf_path))
    bodies = _page_texts(data)
    if not any(bodies):
        _fail(PARSER_NO_TEXT, NO_TEXT_MESSAGE, {"path": str(source)})
    display_title = title.strip() if isinstance(title, str) and title.strip() else source.stem
    markdown, page_records, warnings = _build_markdown(display_title, source, digest, bodies)
    if _sha256_bytes(source.read_bytes()) != digest:
        _fail(MANUAL_PDF_INVALID, "Source PDF changed during extraction", {"path": str(source)})

    workspace = _prepare_workspace(Path(workspace_root))
    from video_paper_wiki_research.light_library_state import try_workspace_lock

    workspace_lock = try_workspace_lock(workspace)
    if workspace_lock is None:
        return _closed(
            LIGHT_WORKSPACE_BUSY,
            "another cooperating operation currently owns this workspace",
            paper_id=f"sha256:{digest}",
        )
    try:
        lock = _try_lock(workspace, digest)
        if lock is None:
            return _closed(
                LIGHT_WORKSPACE_BUSY,
                "another cooperating add currently owns this paper digest",
                paper_id=f"sha256:{digest}",
            )
        try:
            return _extract_locked(
                workspace=workspace,
                source=source,
                data=data,
                digest=digest,
                display_title=display_title,
                markdown=markdown,
                page_records=page_records,
                warnings=warnings,
                title=title,
                page_count=len(bodies),
            )
        finally:
            lock.release()
    finally:
        workspace_lock.release()


def _extract_locked(
    *,
    workspace: Path,
    source: Path,
    data: bytes,
    digest: str,
    display_title: str,
    markdown: str,
    page_records: list[dict[str, Any]],
    warnings: list[str],
    title: str | None,
    page_count: int,
) -> dict[str, Any]:
    _run_inject("after_lock")
    paper_dir = workspace / "papers" / digest
    classified = classify_paper_dir(paper_dir, digest)
    kind = classified["kind"]
    if kind == "complete":
        loaded = classified["loaded"]
        if _title_conflict(loaded, title):
            return _closed(
                LIGHT_PAPER_CONFLICT,
                "explicit title conflicts with the existing paper title",
                paper_id=loaded["paper_id"],
            )
        _cleanup_owned(workspace, digest)
        return _reuse_result(loaded, paper_dir=paper_dir)
    if kind != "absent":
        return _closed(
            SOURCE_INVALID,
            classified.get("reason") or "existing paper directory cannot be reused or replaced",
            paper_id=f"sha256:{digest}",
        )
    recovered = _recover_owned(workspace, digest)
    if recovered is not None:

    }


def restore_backup(archive_path: Path, *, destination: Path) -> dict[str, Any]:
    archive = Path(archive_path).expanduser()
    if not archive.is_absolute():
        archive = Path.cwd() / archive
    if archive.is_symlink() or not archive.is_file():
        fail(LIGHT_BACKUP_INVALID, "archive_path must be a regular file")
    dest_given = Path(destination).expanduser()
    if not dest_given.is_absolute():
        dest_given = Path.cwd() / dest_given
    dest_given = Path(os.path.normpath(dest_given))
    if not has_work_component(dest_given):
        fail(WORKSPACE_INVALID, "destination must be under .work/**", {"path": str(dest_given)})
    if os.path.lexists(dest_given):
        return closed(LIGHT_BACKUP_CONFLICT, "restore destination already exists, including an empty directory")
    parent = dest_given.parent
    parent_resolved = require_work_path(parent, name="destination parent", must_exist=True, kind="dir")
    dest = dest_given
    if dest.resolve().parent != parent_resolved and dest.parent.resolve() != parent_resolved:
        fail(WORKSPACE_INVALID, "destination parent must be a safe .work directory")
    verified = _verify_zip(archive)
    if verified.get("ok") is not True:
        return {key: value for key, value in verified.items() if key not in {"manifest", "contents"}}
    manifest = verified["manifest"]
    contents: dict[str, bytes] = verified["contents"]
    token = secrets.token_hex(8)
    stage = parent_resolved / f".light-backup-stage-{token}"
    payload = stage / "payload"
    if os.path.lexists(stage):
        return closed(LIGHT_BACKUP_CONFLICT, "owned restore staging path already exists")
    try:
        stage.mkdir(exist_ok=False)
        payload.mkdir(exist_ok=False)
        for item in manifest["files"]:
            relative = item["path"]
            error = validate_relpath(relative)
            if error:
                return closed(LIGHT_BACKUP_INVALID, error, path=relative)
            target = payload / relative
            target.parent.mkdir(parents=True, exist_ok=True)
            if target.parent.is_symlink() or not target.parent.is_dir():
                return closed(LIGHT_BACKUP_INVALID, f"restore parent is unsafe for {relative}")
            target.write_bytes(contents[relative])
            os.chmod(target, stat.S_IRUSR | stat.S_IWUSR)
            if sha256_bytes(target.read_bytes()) != item["sha256"]:
                return closed(LIGHT_BACKUP_INVALID, f"restored bytes do not match the manifest for {relative}")
        record = {
            "schema": RESTORATION_SCHEMA,
            "source_archive": str(archive.resolve()),
            "source_workspace_root": manifest["workspace_root"],
            "source_workspace_id": manifest["workspace_id"],
            "destination": str(dest),
            "historical_session_root": manifest["restore_remaps"][f"{WORKFLOW_DIRNAME}/{SESSIONS_DIRNAME}/"],
            "restore_remaps": manifest["restore_remaps"],
        }
        from video_paper_wiki_research.light_library_state import write_persisted_atomic

        (payload / LIBRARY_DIRNAME).mkdir(exist_ok=True)
        write_persisted_atomic(payload / LIBRARY_DIRNAME / "restoration.json", record)
        if os.path.lexists(dest):
            return closed(LIGHT_BACKUP_CONFLICT, "restore destination appeared before publication")
        os.rename(payload, dest)
    finally:
        if os.path.lexists(stage):
            _cleanup_stage(stage)
    historical = dest / manifest["restore_remaps"][f"{WORKFLOW_DIRNAME}/{SESSIONS_DIRNAME}/"].rstrip("/")
    return ok_result(
        "restored a fresh workspace; historical sessions are not active",
        destination=str(dest.resolve()),
        historical_session_root=str(historical),
        workspace_id=manifest["workspace_id"],
        file_count=len(manifest["files"]),
        extra_outputs=manifest["extra_outputs"],
        exclusions=manifest["exclusions"],
        restore_remaps=manifest["restore_remaps"],
        next_actions=[REINDEX_ACTION, REPREPARE_ACTION],
    )


def _cleanup_stage(stage: Path) -> None:
    if stage.is_symlink() or not stage.is_dir():
        return
    for dirpath, dirnames, filenames in os.walk(stage, topdown=False, followlinks=False):
        base = Path(dirpath)
        for name in filenames:
            child = base / name
            if child.is_symlink() or not child.is_file():
                continue
            try:
                child.unlink()
            except OSError:
                pass
        try:
            base.rmdir()
        except OSError:
            pass

        return closed(LIGHT_LIBRARY_CONFLICT, "archive destination is unsafe", paper_id=paper_id, archive_id=archive_id)
    dest_root.mkdir(exist_ok=True)
    manifest = _archive_manifest(archive_id=archive_id, paper_id=paper_id, digest=digest, scanned=scanned)
    write_persisted_atomic(dest_root / "manifest.json", manifest)
    _write_archive_event(
        dest_root,
        {
            "schema": ARCHIVE_EVENT_SCHEMA,
            "archive_id": archive_id,
            "paper_id": paper_id,
            "operation_id": operation_id,
            "state": "archived",
        },
    )
    before = [
        {"path": item["original_relative_path"], "size_bytes": item["size_bytes"], "sha256": item["sha256"]}
        for item in scanned["files"]
    ]
    again = _scan_paper_tree(live, original_prefix=f"{PAPER_DIRNAME}/{digest}")
    if not again.get("ok") or not same_inventory(before, [
        {"path": item["original_relative_path"], "size_bytes": item["size_bytes"], "sha256": item["sha256"]}
        for item in again["files"]
    ]):
        return closed(LIGHT_LIBRARY_CONFLICT, "live paper files changed before archive", paper_id=paper_id, operation_id=operation_id)
    run_library_inject("before_archive_move")
    os.rename(live, payload)
    run_library_inject("after_archive_move")
    error = _validate_archive_payload(dest_root, manifest)
    if error:
        return closed(LIGHT_LIBRARY_NEEDS_RECOVERY, error["message"], paper_id=paper_id, archive_id=archive_id, operation_id=operation_id)
    operation = dict(operation)
    operation["phase"] = "archived"
    _write_operation(workspace, operation)
    return _finish_archive(workspace, operation, scanned)


def _finish_archive(workspace: Path, operation: Mapping[str, Any], scanned: Mapping[str, Any]) -> dict[str, Any]:
    operation = dict(operation)
    operation["phase"] = "complete"
    _write_operation(workspace, operation)
    return ok_result(
        "archived paper; original PDF was not copied or deleted",
        paper_id=operation["paper_id"],
        archive_id=operation["archive_id"],
        operation_id=operation["operation_id"],
        reused=False,
        file_count=len(scanned.get("files") or []),
        next_actions=[REINDEX_ACTION],
    )


def restore_paper(workspace_root: Path, archive_id: str) -> dict[str, Any]:
    archive_id = require_hex_id(archive_id, name="archive_id")
    workspace = require_workspace(workspace_root)
    try:
        with exclusive_workspace_lock(workspace):
            return _restore_locked(workspace, archive_id)
    except _Busy:
        return closed(LIGHT_WORKSPACE_BUSY, "another cooperating operation currently owns this workspace", archive_id=archive_id)


def _restore_locked(
    workspace: Path,
    archive_id: str,
    *,
    operation: dict[str, Any] | None = None,
    acquire_paper_lock: bool = True,
) -> dict[str, Any]:
    dest_root = archive_dir(workspace, archive_id)
    if not is_regular_dir(dest_root):
        return closed(LIGHT_LIBRARY_INVALID, "archive_id is not present", archive_id=archive_id)
    manifest, event = _load_archive_bundle(dest_root)
    if manifest is None:
        return closed(LIGHT_LIBRARY_INVALID, "archive manifest is missing or not persisted canonical JSON", archive_id=archive_id)
    paper_id = manifest.get("paper_id")
    if not is_paper_id(paper_id):
        return closed(LIGHT_LIBRARY_INVALID, "archive manifest paper_id is invalid", archive_id=archive_id)
    digest = paper_digest(str(paper_id))
    lock = _paper_lock(workspace, digest) if acquire_paper_lock else None
    if acquire_paper_lock and lock is None:
        return closed(LIGHT_WORKSPACE_BUSY, "another cooperating operation owns this paper digest", paper_id=paper_id, archive_id=archive_id)
    try:
        live = workspace / PAPER_DIRNAME / digest
        payload = dest_root / "paper"
        payload_present = is_regular_dir(payload)
        live_exists = os.path.lexists(live)
        if operation is None and not payload_present and live_exists and _complete_live(workspace, digest):
            if event and event.get("state") == "restored":
                scanned = _scan_paper_tree(live, original_prefix=f"{PAPER_DIRNAME}/{digest}")
                expected = [
                    {"path": item.get("original_relative_path"), "size_bytes": item.get("size_bytes"), "sha256": item.get("sha256")}
                    for item in manifest.get("files") or []
                    if type(item) is dict
                ]
                if scanned.get("ok") and same_inventory(
                    expected,
                    [
                        {"path": item["original_relative_path"], "size_bytes": item["size_bytes"], "sha256": item["sha256"]}
                        for item in scanned["files"]
                    ],
                ):
                    return ok_result(
                        "archive is already restored",
                        paper_id=paper_id,
                        archive_id=archive_id,
                        operation_id=None if operation is None else operation.get("operation_id"),
                        reused=True,
                        next_actions=[REINDEX_ACTION],
                    )
            return closed(LIGHT_LIBRARY_CONFLICT, "live paper slot already exists and is not an exact restore of this archive", paper_id=paper_id, archive_id=archive_id)
        if live_exists and payload_present:
            return closed(LIGHT_LIBRARY_CONFLICT, "archive payload and live paper both exist", paper_id=paper_id, archive_id=archive_id)
        if not payload_present and not live_exists:
            return closed(LIGHT_LIBRARY_NEEDS_RECOVERY, "neither archive payload nor live paper is present", paper_id=paper_id, archive_id=archive_id)
        error = _validate_archive_payload(dest_root, manifest) if payload_present else None
        if error:
            return closed(error["status"], error["message"], paper_id=paper_id, archive_id=archive_id)
        ensure_library_dirs(workspace)
        if operation is None:
            operation = {
                "schema": OPERATION_SCHEMA,
                "operation_id": new_hex_id(),
                "kind": "restore",
                "paper_id": paper_id,
                "archive_id": archive_id,
                "phase": "intent",
                "owned_relative_paths": [
                    f"{PAPER_DIRNAME}/{digest}/",
                    f"{LIBRARY_DIRNAME}/{ARCHIVE_DIRNAME}/{archive_id}/",
                ],
                "source_inventory": [
                    {"path": item["original_relative_path"], "size_bytes": item["size_bytes"], "sha256": item["sha256"]}
                    for item in manifest["files"]
                    if type(item) is dict
                ],
                "file_inventory": list(manifest["files"]),
            }
            _write_operation(workspace, operation)
            run_library_inject("after_intent")
        papers_root = workspace / PAPER_DIRNAME
        if not is_regular_dir(papers_root):
            papers_root.mkdir(exist_ok=True)
        if not payload_present and live_exists and _complete_live(workspace, digest):
            _write_archive_event(
                dest_root,
                {
                    "schema": ARCHIVE_EVENT_SCHEMA,
                    "archive_id": archive_id,
                    "paper_id": paper_id,
                    "operation_id": operation["operation_id"],
                    "state": "restored",
                },
            )
            operation = dict(operation)
            operation["phase"] = "complete"
            _write_operation(workspace, operation)
            return ok_result(
                "recognized an already completed restore move",
                paper_id=paper_id,
                archive_id=archive_id,
                operation_id=operation["operation_id"],
                reused=True,
                next_actions=[REINDEX_ACTION],
            )
        if os.path.lexists(live):
            return closed(LIGHT_LIBRARY_CONFLICT, "refusing to overwrite an existing live paper", paper_id=paper_id, archive_id=archive_id)
        run_library_inject("before_restore_move")
        os.rename(payload, live)
        run_library_inject("after_restore_move")
        classified = classify_paper_dir(live, digest)
        if classified["kind"] != "complete":
            return closed(LIGHT_LIBRARY_NEEDS_RECOVERY, "restored directory is not a valid live paper", paper_id=paper_id, archive_id=archive_id)
        _write_archive_event(
            dest_root,
            {
                "schema": ARCHIVE_EVENT_SCHEMA,
                "archive_id": archive_id,
                "paper_id": paper_id,
                "operation_id": operation["operation_id"],
                "state": "restored",
            },
        )
        operation = dict(operation)
        operation["phase"] = "complete"
        _write_operation(workspace, operation)
        return ok_result(
            "restored archived paper to its original slot",
            paper_id=paper_id,
            archive_id=archive_id,
            operation_id=operation["operation_id"],
            reused=False,
            next_actions=[REINDEX_ACTION],
        )
    finally:
        if lock is not None:
            lock.release()


