    paper_id = require_paper_id(paper_id)

def _discard_owned_stage(workspace: Path, operation: Mapping[str, Any]) -> bool:
    staged = staging_dir(workspace, str(operation["operation_id"]))
    if not os.path.lexists(staged):
        return True
    if staged.is_symlink() or not staged.is_dir():
        return False
    owner = load_persisted_object(staged / "ownership.json")
    if owner is None or owner.get("schema") != STAGING_OWNER_SCHEMA or owner.get("operation_id") != operation["operation_id"]:
        return False
    names = set(list_names(staged))
    if names - {"ownership.json", "workspace"}:
        return False
    workspace_dir = staged / "workspace"
    if os.path.lexists(workspace_dir):
        if workspace_dir.is_symlink() or not workspace_dir.is_dir():
            return False
        _rmtree_owned(workspace_dir)
    owner_path = staged / "ownership.json"
    if is_regular_file(owner_path):
        owner_path.unlink()
    try:
        staged.rmdir()
    except OSError:
        return False
    return True


def _rmtree_owned(path: Path) -> None:
    if path.is_symlink() or not path.is_dir():
        return
    for child in list(path.iterdir()):
        if child.is_symlink():
            continue
        if child.is_dir():
            _rmtree_owned(child)
        elif child.is_file():
            child.unlink()
    try:
        path.rmdir()
    except OSError:
        return


def recover_library(workspace_root: Path, *, operation_id: str | None = None) -> dict[str, Any]:
    if operation_id is not None:
        operation_id = require_hex_id(operation_id, name="operation_id")
    workspace = require_workspace(workspace_root)
    try:
        with exclusive_workspace_lock(workspace):
            return _recover_locked(workspace, operation_id=operation_id)
    except _Busy:
        return closed(LIGHT_WORKSPACE_BUSY, "another cooperating operation currently owns this workspace")


def _recover_locked(workspace: Path, *, operation_id: str | None) -> dict[str, Any]:
    results: list[dict[str, Any]] = []
    paths = iter_operation_files(workspace)
    selected: list[Path] = []
    for path in paths:
        loaded = load_persisted_object(path)
        recognized = recognized_operation(loaded)
        if recognized is None:
            results.append(
                closed(
                    LIGHT_LIBRARY_INVALID,
                    "malformed or foreign operation journal was preserved",
                    path=str(path.relative_to(workspace)),
                )
            )
            continue
        if operation_id is not None and recognized["operation_id"] != operation_id:
            continue
        selected.append(path)
        results.append(_recover_one(workspace, recognized))
    if operation_id is not None and not selected:
        return closed(LIGHT_LIBRARY_INVALID, "operation_id is not a recognized journal", operation_id=operation_id, operations=results)
    failed = [item for item in results if item.get("ok") is not True]
    if failed:
        return closed(
            str(failed[0].get("status") or LIGHT_LIBRARY_NEEDS_RECOVERY),
            "one or more library operations still need attention",
            operations=results,
            next_actions=[RECOVER_ACTION],
        )
    return ok_result("inspected recognized library operations", operations=results)


def _recover_one(workspace: Path, operation: dict[str, Any]) -> dict[str, Any]:
    if operation.get("phase") == "complete":
        return ok_result(
            "operation is already complete",
            operation_id=operation["operation_id"],
            kind=operation["kind"],
            phase="complete",
            reused=True,
        )
    kind = operation.get("kind")
    paper_id = operation.get("paper_id")
    digest = paper_digest(str(paper_id)) if is_paper_id(paper_id) else None
    lock = _paper_lock(workspace, digest) if digest else None
    if digest and lock is None:
        return closed(LIGHT_WORKSPACE_BUSY, "another cooperating operation owns this paper digest", operation_id=operation["operation_id"], paper_id=paper_id)
    try:
        if kind == "archive":
            if not is_paper_id(paper_id):
                return closed(LIGHT_LIBRARY_NEEDS_RECOVERY, "archive journal is missing paper_id", operation_id=operation["operation_id"])
            return _archive_locked(workspace, str(paper_id), operation=operation)
        if kind == "restore":
            archive_id = operation.get("archive_id")
            if not is_hex_id(archive_id):
                return closed(LIGHT_LIBRARY_NEEDS_RECOVERY, "restore journal is missing archive_id", operation_id=operation["operation_id"])
            return _restore_locked(workspace, str(archive_id), operation=operation, acquire_paper_lock=False)
        if kind == "replace":
            if not is_paper_id(paper_id):
                return closed(LIGHT_LIBRARY_NEEDS_RECOVERY, "replace journal is missing paper_id", operation_id=operation["operation_id"])
            phase = operation.get("phase")
            if phase == "intent":
                staged = staging_dir(workspace, str(operation["operation_id"]))
                owner = load_persisted_object(staged / "ownership.json") if is_regular_dir(staged) else None
                if owner and owner.get("operation_id") == operation["operation_id"]:
                    if _discard_owned_stage(workspace, operation):
                        return closed(
                            LIGHT_LIBRARY_NEEDS_RECOVERY,
                            "pre-staging replacement failed; old live paper is intact and the owned stage was discarded",
                            operation_id=operation["operation_id"],
                            paper_id=paper_id,
                        )
                return closed(
                    LIGHT_LIBRARY_NEEDS_RECOVERY,
                    "replacement did not finish staging; retry replace_paper with the original PDF",
                    operation_id=operation["operation_id"],
                    paper_id=paper_id,
                )
            return _replace_forward(workspace, operation, pdf_path=None, scanned_old=None)
        return closed(LIGHT_LIBRARY_INVALID, "unrecognized operation kind was preserved", operation_id=operation.get("operation_id"))
    finally:
        if lock is not None:
            lock.release()


def library_backup_blockers(workspace: Path) -> dict[str, Any] | None:
    """Return a closed refusal if library/knowledge/PDF publication state is unsafe to back up."""
    pending = pending_operation_ids(workspace)
    if pending:
        return closed(
            LIGHT_LIBRARY_NEEDS_RECOVERY,
            "pending library operations must be recovered before backup",
            pending_operation_ids=pending,
            next_actions=[RECOVER_ACTION],
        )
    diagnostics = library_diagnostics(workspace)
    if any(item["code"] in {"LIBRARY_STAGING_NONEMPTY", "LIBRARY_JOURNAL_FOREIGN"} for item in diagnostics):
        return closed(
            LIGHT_LIBRARY_NEEDS_RECOVERY,
            "library staging or foreign journals must be resolved before backup",
            diagnostics=diagnostics,
            next_actions=[RECOVER_ACTION],
        )
    if knowledge_staging_nonempty(workspace):
        return closed(
            LIGHT_LIBRARY_NEEDS_RECOVERY,
            "nonempty knowledge staging must be recovered by retrying import/build before backup",
            next_actions=["Retry the knowledge import or build that owns the staging directory."],
        )
    transactions = classify_transaction_tree(workspace)
    if transactions["kind"] in {"pending", "unknown", "unsafe"}:
        return closed(
            LIGHT_LIBRARY_NEEDS_RECOVERY,
            transactions.get("message") or "PDF transaction state is unsafe to back up",
        )
    index = classify_index_tree(workspace)
    if index["kind"] in {"unknown", "unsafe"}:
        return closed(LIGHT_LIBRARY_INVALID, index.get("message") or "index tree contains unrecognized extra content")
    return None

def _ensure_transaction_dir(workspace: Path) -> Path:
    tx_dir = workspace / TRANSACTIONS_DIR
    _ensure_regular_dir(tx_dir, create=True, label=".light-transactions")
    return tx_dir


class _AdvisoryLock:
    def __init__(self, fd: int) -> None:
        self.fd = fd

    def release(self) -> None:
        if self.fd is None:
            return
        try:
            fcntl.flock(self.fd, fcntl.LOCK_UN)
        finally:
            os.close(self.fd)
            self.fd = None  # type: ignore[assignment]


def lock_path_for(workspace: Path, digest: str) -> Path:
    return workspace / TRANSACTIONS_DIR / f"{digest}.lock"


def _try_lock(workspace: Path, digest: str) -> _AdvisoryLock | None:
    _ensure_transaction_dir(workspace)
    path = lock_path_for(workspace, digest)
    if path.is_symlink() or (os.path.lexists(path) and not path.is_file()):
        _fail(WORKSPACE_INVALID, "lock path must be a regular file", {"path": str(path)})
    flags = os.O_RDWR | os.O_CREAT | getattr(os, "O_NOFOLLOW", 0)
    try:
        fd = os.open(path, flags, 0o644)
    except OSError as exc:
        _fail(WORKSPACE_INVALID, "lock path is not a writable regular file", {"path": str(path)})
        raise AssertionError("unreachable") from exc
    try:
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        os.close(fd)
        return None
    except OSError:
        os.close(fd)
        return None
    return _AdvisoryLock(fd)


def lock_is_held(lock_path: Path) -> bool:
    """True only when another process currently holds the advisory lock."""
    if lock_path.is_symlink() or not lock_path.is_file():
        return False
    try:
        fd = os.open(lock_path, os.O_RDWR)
    except OSError:
        return False
    try:
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        return True
    except OSError:
        return False
    try:
        fcntl.flock(fd, fcntl.LOCK_UN)
    finally:
        os.close(fd)
    return False


def _entry_kind(path: Path) -> str:
    if path.is_symlink():
        return "symlink"
    if path.is_file():
        return "file"
    if path.is_dir():
        return "dir"
    return "other"


def _list_names(directory: Path) -> list[str]:
    try:
        return sorted(item.name for item in directory.iterdir())
    except OSError:
        return []


def _decode_pair(directory: Path) -> tuple[str, str] | None:
    try:
        markdown = (directory / "source.md").read_bytes().decode("utf-8")
        raw_json = (directory / "source.json").read_bytes().decode("utf-8")
    except (OSError, UnicodeError):
        return None
    return markdown, raw_json


def _validate_payload(directory: Path, digest: str) -> dict[str, Any]:
    """Validate a two-file payload against digest. Directory name may be a staging token."""
    if _entry_kind(directory) != "dir":
        return {"kind": "unsafe", "reason": "payload path is not a regular directory"}
    names = _list_names(directory)
    kinds = {name: _entry_kind(directory / name) for name in names}
    if any(name not in PAYLOAD_NAMES for name in names) or any(kinds[name] != "file" for name in names):
        return {"kind": "unknown", "reason": "owned payload set is not exactly two regular files", "names": names}
    if any(name not in kinds for name in PAYLOAD_NAMES):
        return {"kind": "partial", "reason": "owned payload is incomplete", "names": names}
    decoded = _decode_pair(directory)
    if decoded is None:
        return {"kind": "invalid", "reason": "paper files are not valid UTF-8", "code": SOURCE_INVALID, "names": names}
    markdown, raw_json = decoded
    try:
        meta = json.loads(raw_json)
    except json.JSONDecodeError:
        return {"kind": "invalid", "reason": "source.json is not valid JSON", "code": SOURCE_INVALID, "names": names}
    if type(meta) is not dict:
        return {"kind": "invalid", "reason": "source.json root must be an object", "code": SOURCE_INVALID, "names": names}
    if meta.get("schema") != SCHEMA or meta.get("paper_id") != f"sha256:{digest}":
        return {"kind": "identity", "reason": "source.json paper identity differs", "code": SOURCE_INVALID, "names": names}
    source = meta.get("source") if type(meta.get("source")) is dict else {}
    if source.get("sha256") != digest:
        return {"kind": "identity", "reason": "source.json identity does not match the PDF digest", "code": SOURCE_INVALID, "names": names}
    document = meta.get("document")
    if type(document) is not dict or document.get("path") != f"papers/{digest}/source.md":
        return {"kind": "invalid", "reason": "source.md digest or path differs from source.json", "code": SOURCE_INVALID, "names": names}
    if type(meta.get("page_count")) is not int:
        return {"kind": "invalid", "reason": "source.json pages are invalid", "code": SOURCE_INVALID, "names": names}
    try:
        _locate_pages(markdown, page_count=meta["page_count"])
    except ResearchError as exc:
        return {"kind": "invalid", "reason": exc.message, "code": exc.code or SOURCE_INVALID, "names": names}
    return {"kind": "complete", "names": names, "metadata": meta}


def classify_paper_dir(directory: Path, digest: str) -> dict[str, Any]:
    """Classify papers/<digest> without deleting anything."""
    if not os.path.lexists(directory):
        return {"kind": "absent"}
    kind = _entry_kind(directory)
    if kind != "dir":
        return {"kind": "unsafe", "reason": "paper path is not a regular directory"}
    names = _list_names(directory)
    seen: dict[str, str] = {}
    extras: list[str] = []
    for name in names:
        child = directory / name
        seen[name] = _entry_kind(child)
        if name in PAYLOAD_NAMES:
            continue
        extras.append(name)
    for required in PAYLOAD_NAMES:
        if required not in seen:
            return {"kind": "partial", "reason": f"missing {required}", "names": names}
        if seen[required] != "file":
            return {"kind": "unsafe", "reason": f"{required} is not a regular file", "names": names}
    for name in extras:
        if seen[name] != "file":
            return {"kind": "unsafe", "reason": f"unexpected {seen[name]} {name}", "names": names}
    decoded = _decode_pair(directory)
    if decoded is None:
        return {"kind": "invalid", "reason": "paper files are not valid UTF-8", "code": SOURCE_INVALID, "names": names}
    try:
        loaded = _load_paper(directory)
    except ResearchError as exc:
        return {"kind": "invalid", "reason": exc.message, "code": exc.code, "names": names}
    except (UnicodeError, json.JSONDecodeError):
        return {"kind": "invalid", "reason": "paper files are not valid UTF-8 JSON/Markdown", "code": SOURCE_INVALID, "names": names}
    source = loaded["metadata"].get("source")
    source_sha = source.get("sha256") if type(source) is dict else None
    if type(source_sha) is not str or source_sha != digest or directory.name != digest:
        return {
            "kind": "identity",
            "reason": "source.json identity does not match the PDF digest",
            "names": names,
            "loaded": loaded,
        }
    return {"kind": "complete", "names": names, "loaded": loaded, "extras": extras}


