def _marker_payload(digest: str, token: str) -> dict[str, Any]:
    staging_rel = f"{TRANSACTIONS_DIR}/{STAGING_DIRNAME}/{digest}--{token}"
    return {
        "schema": TRANSACTION_SCHEMA,
        "digest": digest,
