LIGHT_LIBRARY_NEEDS_RECOVERY = "LIGHT_LIBRARY_NEEDS_RECOVERY"
LIGHT_BACKUP_INVALID = "LIGHT_BACKUP_INVALID"
LIGHT_BACKUP_CONFLICT = "LIGHT_BACKUP_CONFLICT"

LIBRARY_DIRNAME = ".light-library"
