def _same_file_inventory(left: list[Mapping[str, Any]], right: list[Mapping[str, Any]]) -> bool:
    def _rows(items: list[Mapping[str, Any]]) -> list[tuple[str, str, int, str]] | None:
        rows: list[tuple[str, str, int, str]] = []
        seen: set[str] = set()
