            archive_id=None,
            operation_id=None,
            reused=True,
            retained_note_paths=[],
            next_actions=[],
        )
    completed = _matching_replace_events(
        workspace,
        paper_id=paper_id,
        new_paper_id=new_paper_id,
        title=title,
