    OUTCOME_ABORTED_BEFORE_STAGING,
    OUTCOME_ARCHIVED,
    OUTCOME_REPLACED,
    OUTCOME_RESTORED,
    PAPER_DIRNAME,
    SOURCE_INVALID,
    STAGING_DIRNAME,
    STAGING_OWNER_FIELDS,
    STAGING_OWNER_SCHEMA,
