    posix_rel,
    recognized_operation,
    require_hex_id,
    require_paper_id,
    require_workspace,
    run_library_inject,
    same_inventory,
    sha256_bytes,
    source_from_file_inventory,
    staging_dir,
    validate_directory_inventory,
    validate_file_inventory,
    walk_regular_tree,
    write_bytes_atomic,
