            return "member timestamp must be 1980-01-01 00:00:00"
        if csize == 0xFFFFFFFF or usize == 0xFFFFFFFF or local_off == 0xFFFFFFFF:
            return "ZIP64 metadata is refused"
        extra = data[cursor + 46 + name_len : cursor + 46 + name_len + extra_len]
        comment = data[cursor + 46 + name_len + extra_len : cursor + 46 + name_len + extra_len + comment_len_c]
        if extra or comment or _extra_has_zip64(extra):
            return "ZIP extra fields and comments are refused"
        if external != ZIP_EXTERNAL_ATTR:
            return "ZIP member attributes must be private regular files"
        local_offsets.append(local_off)
        cursor += 46 + name_len + extra_len + comment_len_c
    if cursor != eocd_off:
        return "ZIP central directory size is inconsistent"
    for local_off in local_offsets:
        if local_off + 30 > len(data) or data[local_off : local_off + 4] != b"PK\x03\x04":
            return "ZIP local header is malformed"
        needed, flags, method, mtime, mdate, _crc, csize, usize, name_len, extra_len = struct.unpack_from(
            "<HHHHHIIIHH", data, local_off + 4
        )
        if needed >= 45 or flags & 0x1 or method != 0:
            return "ZIP64, encrypted, or compressed members are refused"
        if mtime != 0 or mdate != 0x0021:
            return "member timestamp must be 1980-01-01 00:00:00"
        if csize == 0xFFFFFFFF or usize == 0xFFFFFFFF:
            return "ZIP64 metadata is refused"
        extra = data[local_off + 30 + name_len : local_off + 30 + name_len + extra_len]
